mapper.select:
select * from repro_events
where house_id = #{houseId} and request_id = #{requestId}
limit 1

select * from repro_events
where house_id = #{houseId} and cycle_id = #{cycleId}
order by occurred_at, id

select * from repro_events
where house_id = #{houseId} and mother_rabbit_id = #{motherRabbitId}
order by occurred_at desc, id desc
limit #{limit}

select * from repro_events
where house_id = #{houseId}
  and batch_id = #{batchId}
  and mother_rabbit_id = #{motherRabbitId}
order by occurred_at desc, id desc
limit #{limit}
